// Unit tests for the WebVTT parser used by historical-recording subtitles.
// Run: npm run test:unit   (Node's built-in test runner; no extra dependencies)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseVtt, activeCueText } from './vtt.ts';

const SAMPLE = [
  '﻿WEBVTT',
  '',
  'NOTE generated by the old platform',
  '',
  '1',
  '00:00:01.000 --> 00:00:03.500 align:center',
  '<v Teacher>Namaskaram, everyone</v>',
  '',
  '00:04.250 --> 00:06.000',
  'Short <i>mm:ss</i> timestamps',
  'second line',
  '',
  '01:00:00,000 --> 01:00:02,000',
  'Comma &amp; hours',
  '',
].join('\r\n');

test('parses cues with ids, settings, mm:ss and comma timestamps', () => {
  const cues = parseVtt(SAMPLE);
  assert.equal(cues.length, 3);
  assert.deepEqual(cues[0], { start: 1, end: 3.5, text: 'Namaskaram, everyone' });
  assert.deepEqual(cues[1], { start: 4.25, end: 6, text: 'Short mm:ss timestamps\nsecond line' });
  assert.deepEqual(cues[2], { start: 3600, end: 3602, text: 'Comma & hours' });
});

test('skips header, NOTE/STYLE blocks, empty and invalid cues', () => {
  const cues = parseVtt('WEBVTT\n\nSTYLE\n::cue { color: red }\n\n00:00:05.000 --> 00:00:04.000\nbackwards\n\n00:00:01.000 --> 00:00:02.000\n\n');
  assert.equal(cues.length, 0);
  assert.deepEqual(parseVtt(''), []);
  assert.deepEqual(parseVtt('not a subtitle file'), []);
});

test('activeCueText returns the cue showing at a time', () => {
  const cues = parseVtt(SAMPLE);
  assert.equal(activeCueText(cues, 0.5), '');
  assert.equal(activeCueText(cues, 1), 'Namaskaram, everyone');
  assert.equal(activeCueText(cues, 3.49), 'Namaskaram, everyone');
  assert.equal(activeCueText(cues, 3.5), ''); // end is exclusive
  assert.equal(activeCueText(cues, 5), 'Short mm:ss timestamps\nsecond line');
  assert.equal(activeCueText(cues, 3601), 'Comma & hours');
  assert.equal(activeCueText([], 10), '');
});

test('overlapping cues are shown together', () => {
  const cues = parseVtt('WEBVTT\n\n00:00:01.000 --> 00:00:05.000\nfirst\n\n00:00:02.000 --> 00:00:03.000\nsecond\n');
  assert.equal(activeCueText(cues, 2.5), 'first\nsecond');
  assert.equal(activeCueText(cues, 4), 'first');
});

test('handles thousands of cues quickly (binary search)', () => {
  const lines = ['WEBVTT', ''];
  for (let i = 0; i < 5000; i++) {
    const s = i * 2;
    const fmt = (t) => `${String(Math.floor(t / 3600)).padStart(2, '0')}:${String(Math.floor((t % 3600) / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}.000`;
    lines.push(`${fmt(s)} --> ${fmt(s + 1)}`, `cue ${i}`, '');
  }
  const cues = parseVtt(lines.join('\n'));
  assert.equal(cues.length, 5000);
  assert.equal(activeCueText(cues, 2 * 4321 + 0.5), 'cue 4321');
  assert.equal(activeCueText(cues, 2 * 4321 + 1.5), '');
});
